import {assess} from './capstone-model.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>new Intl.NumberFormat('en-GB',{maximumFractionDigits:1}).format(v);
export function readinessBanner(state){const a=assess(state);return `<a class="readiness-banner" href="#insights"><span><strong>${a.alerts.length?`${a.alerts.length} items need review`:'Automated checks: no flags detected'}</strong> · Review data quality, insights and next steps</span><span aria-hidden="true">→</span></a>`;}
function trend(state,c){
 if(!c.ready)return '<div class="empty trend-empty"><h3>Build a comparable baseline</h3><p>No prior-year data is preloaded. Enter all three scope subtotals for the previous year, cite their source, and confirm the same boundary and accounting method.</p><button class="btn" data-action="baseline">Add previous year</button></div>';
 const total=c.metrics[0],max=Math.max(total.previous,total.current??0,1),y=v=>190-v/max*140;
 const chart=total.current===null?'<p class="demo-note">The annual total trend is unavailable: each current scope needs calculated rows with no missing inputs.</p>':`<svg class="annual-chart" viewBox="0 0 640 245" role="img" aria-label="Calculated subtotal: ${state.previous.year}, ${fmt(total.previous)} tonnes CO2e; ${state.year}, ${fmt(total.current)} tonnes CO2e. Two annual observations, same user-confirmed boundary."><line x1="85" y1="190" x2="550" y2="190" stroke="var(--color-rule)"/><text x="20" y="194">0</text><path d="M150 ${y(total.previous)} L490 ${y(total.current)}" fill="none" stroke="var(--color-accent)" stroke-width="3"/>${[[150,total.previous,state.previous.year],[490,total.current,state.year]].map(([x,v,year])=>`<circle cx="${x}" cy="${y(v)}" r="6" fill="var(--color-accent)"/><text x="${x}" y="${y(v)-17}" text-anchor="middle">${fmt(v)} t CO₂e</text><text x="${x}" y="222" text-anchor="middle">${year}</text>`).join('')}</svg>`;
 return chart+`<div class="table-wrap"><table class="comparison-table"><thead><tr><th>Indicator · t CO₂e</th><th class="num">${state.previous.year}</th><th class="num">${state.year}</th><th class="num">Change</th></tr></thead><tbody>${c.metrics.map(m=>`<tr><td>${m.label}</td><td class="num">${fmt(m.previous)}</td><td class="num">${m.current===null?'Unknown':fmt(m.current)}</td><td class="num">${m.percent===null?'—':`${m.percent>0?'+':''}${fmt(m.percent)}%`}</td></tr>`).join('')}</tbody></table></div><p class="panel-foot">Prior-year source: ${esc(state.previous.source)}. Comparability is user-confirmed, not independently verified. A zero baseline has no percentage change. The line connects two annual observations; it does not imply a monthly trend.</p>`;
}
export function renderCapstone(state){
 const a=assess(state),q=a.quality;
 const checks=[['Missing quantity / factor',q.missing,`${q.missing} of ${state.rows.length} rows`],['Factor source notes',q.unsourced,`${q.unsourced} undocumented`],['Possible duplicate rows',q.duplicates,`${q.duplicates} need review`],['Illustrative assumptions',q.illustrative,`${q.illustrative} rows to replace`],['Scope 3 category review',q.unassessed,`${q.unassessed} incomplete or unassessed`]];
 return `<div class="page-head"><div><h1>Insights & readiness</h1><p>From evidence to a decision · ${esc(state.company)} · FY ${state.year}</p></div><div class="head-actions"><button class="btn" data-action="tableau-export">Export for Tableau</button><button class="btn primary" data-action="brief">Presentation outline</button></div></div>
 <section class="panel capstone-problem"><span class="eyebrow">The business problem</span><h2>Where should manufacturing reduce emissions first?</h2><p>Connect operating and purchasing activity to a transparent Scope 1, 2 and 3 estimate, identify the largest entered sources, and assign measurable actions. This independent Unilever Indonesia case study demonstrates the method; sample data cannot establish the company’s actual footprint.</p></section>
 <section class="panel capstone-section"><div class="panel-head"><div><h2>Red flags & follow-up</h2><p>Screening rules inspired by the Week 7 presentation; these are not regulatory thresholds.</p></div><span class="chip">${a.alerts.length} flagged</span></div><div class="flag-grid">${a.alerts.length?a.alerts.map(v=>`<article class="flag"><strong>${esc(v.title)}</strong><p>${esc(v.detail)}</p></article>`).join(''):'<p>No automated flags detected. This does not establish completeness or assurance.</p>'}</div><a href="#activities" class="text-btn">Review activity evidence →</a></section>
 <section class="capstone-section"><div class="panel-head"><div><h2>Three insights from the entered data</h2><p>Observation → business implication → next step. Recalculated whenever the inventory changes.</p></div></div><div class="insight-grid">${a.insights.length?a.insights.map((v,i)=>`<article class="panel insight-card"><span class="insight-no">0${i+1}</span><h3>${esc(v.title)}</h3><p><strong>Observation</strong>${esc(v.observation)}</p><p><strong>Why it matters</strong>${esc(v.meaning)}</p><p><strong>Next step</strong>${esc(v.next)}</p></article>`).join(''):'<div class="panel empty">Add calculated activity data with a positive subtotal to generate evidence-based insights.</div>'}</div></section>
 <section class="panel capstone-section"><div class="panel-head"><div><h2>Annual trend</h2><p>Calculated subtotal · matching inventory boundary · t CO₂e</p></div><button class="btn small" data-action="baseline">${state.previous?'Edit':'Add'} previous year</button></div>${trend(state,a.comparison)}<details class="rule-note"><summary>How the trend alerts work</summary><p>Total increase &gt;10% or Scope 2 increase &gt;15% triggers a review. An undocumented, non-adjacent or unconfirmed baseline disables comparison. Missing current scope inputs block that scope’s comparison and the total comparison. Two-consecutive-increase alerts require three periods and are not implemented in this two-period view.</p></details></section>
 <section class="capstone-section"><div class="panel-head"><div><h2>Three priority recommendations</h2><p>Ranked by standalone scenario potential. Suggested owners and timing are proposals for review.</p></div><a class="text-btn" href="#plan">Adjust assumptions →</a></div><div class="recommendation-grid">${a.recommendations.length?a.recommendations.map((r,i)=>`<article class="panel"><span class="eyebrow">Priority ${i+1} · ${esc(r.owner)}</span><h3>${esc(r.title)}</h3><p>${esc(r.next)}</p><dl><dt>Monitor</dt><dd>${esc(r.metric)}</dd><dt>Scenario target</dt><dd>${r.percent}% reduction in the targeted source(s): ${fmt(r.impact)} t CO₂e standalone potential. Assumption, not a commitment.</dd><dt>Implementation window</dt><dd>${esc(r.horizon)} · ${esc(r.effort)}</dd></dl></article>`).join(''):'<div class="panel empty">No positive reduction estimates yet. Add relevant activities and set scenario percentages in Reduction plan.</div>'}</div><p class="muted capstone-note">Standalone savings are not additive when actions overlap. Use the combined scenario in Reduction plan for the total.</p></section>
 <section class="panel capstone-section"><div class="panel-head"><div><h2>Dataset readiness</h2><p>Automated checks support review; they do not verify source reliability.</p></div></div><div class="quality-grid">${checks.map(([label,count,detail])=>`<div class="quality-item"><strong>${label}</strong><span class="${count?'quality-warning':'quality-clear'}">${detail}</span></div>`).join('')}</div><p class="panel-foot">Year: ${state.year}. Units are validated against the factor denominator; quantities in different units are not summed. Duplicate checks compare matching normalized activity fields and never remove rows. Record factor publisher, year, geography and reference in each source note. “User supplied” does not mean verified.</p></section>
 <section class="panel capstone-section"><h2>Capstone submission checklist</h2><ul class="check-list"><li><strong>Indicators:</strong> subtotal, Scope 1, Scope 2, Scope 3, production intensity, category coverage and potential reduction.</li><li><strong>Visualizations:</strong> scope comparison, ranked source bars, treemap and reduction waterfall in Visual analytics; annual trend once a comparable baseline is entered.</li><li><strong>Decision support:</strong> red flags, three evidence-based insights and three measurable recommendations when sufficient data exists.</li><li><strong>Still requires your evidence:</strong> verified company dataset, complete boundary review, actual team details and a sourced prior-year baseline.</li></ul><button class="btn" data-action="brief">Open seven-slide draft outline</button><p class="panel-foot">Reference: Preparing the Capstone Project, Dr. Eng. Niki Prastomo, Week 7 (2026), slides 4–18.</p></section>`;
}
export function presentationOutline(state){const a=assess(state);return `# Carbon Ledger — seven-slide capstone draft

All figures below are from the current session and are a partial, unverified inventory. Sample values are illustrative, not Unilever's reported emissions. Replace sample evidence before presenting company results.

## 1. Title & team
Carbon Ledger: manufacturing carbon management for ${state.company}
Reporting year: ${state.year}. Add actual presenter names, roles and course details.

## 2. Problem statement
How can a manufacturer identify material emission sources and assign measurable reduction actions when operational and supply-chain records are fragmented?
Audience: operations, engineering, procurement and sustainability managers.

## 3. Data source & dataset
${state.rows.length} activity rows; ${a.quality.illustrative} illustrative; ${a.quality.missing} missing quantity/factor; ${a.quality.unsourced} undocumented source notes; ${a.quality.duplicates} possible duplicates.
Export the rectangular Tableau dataset. Show source notes, reporting year, scope/category labels and units. Replace assumptions with activity records and documented factors.

## 4. Calculation logic / method
Activity quantity × factor (kg CO2e per matching unit) ÷ 1,000 = t CO2e.
Scope 2 is location-based. Missing data is excluded, not zero. Partial inventory; category coverage does not prove completeness. Overlapping reductions compound.

## 5. Dashboard demonstration
Calculated subtotal: ${a.calculation.calculated?fmt(a.calculation.total):'Unknown'} t CO2e.
Show the scope comparison, ranked sources, treemap and reduction waterfall. Change one input and trace the recalculation. ${a.comparison.ready?'Show the user-confirmed prior-year comparison and its source.':'Explain that annual trend is unavailable until a documented comparable baseline is supplied.'}
${a.comparison.ready?`Baseline year: ${state.previous.year}. Source and boundary notes: ${state.previous.source}.\n${a.comparison.metrics.map(m=>`${m.label}: ${fmt(m.previous)} → ${m.current===null?'Unknown':fmt(m.current)} t CO2e; change ${m.percent===null?'not available':fmt(m.percent)+'%'}.`).join('\n')}`:''}

## 6. Key insights & red flags
${a.insights.length?a.insights.map((v,i)=>`${i+1}. ${v.observation} ${v.meaning} Next: ${v.next}`).join('\n'):'Insufficient positive calculated data for insights.'}
Flags:
${a.alerts.map(v=>`- ${v.title}: ${v.detail}`).join('\n')||'- No automated flags; this is not an assurance opinion.'}

## 7. Recommendations & next steps
${a.recommendations.map((r,i)=>`${i+1}. ${r.title}. Owner: ${r.owner}. ${r.next} Monitor: ${r.metric}. Scenario: ${r.percent}% source reduction, ${fmt(r.impact)} t CO2e standalone potential over ${r.horizon}.`).join('\n')||'Add relevant activity data and scenario assumptions before proposing quantified reductions.'}
Validate feasibility, cost and operational constraints before approving investment. Savings are scenarios, not achieved outcomes. Confirm the boundary, replace illustrative inputs, and record actual results against the same production denominator.

Reference: Preparing the Capstone Project, Dr. Eng. Niki Prastomo (2026), slides 4–18.
`;}
